"""Shared scaffolding for every emitter.

An emitter turns a validated `RouteMap` into one source file. Emitters never
re-derive anything the model already decided (method sets, optionality, wire
names) -- that is what kept v1's five hand-written method-inference tables from
agreeing with each other.
"""

from __future__ import annotations

from dataclasses import dataclass

from ..model import (
    DELIVERY_OPTO_SYNC,
    ListOf,
    MapOf,
    Named,
    OptionOf,
    Route,
    RouteMap,
    TypeExpr,
)

BANNER = "Generated by ridl from {source}. DO NOT EDIT."
PROVENANCE = (
    "Edit the route map and re-run `ridl generate`; a drift check fails the "
    "build if this file and the map disagree."
)


@dataclass
class Emitted:
    """One generated file: a path relative to the output root, plus contents."""

    path: str
    text: str


class Writer:
    """A tiny indent-aware string builder. Emitters stay readable and the
    output stays byte-stable, which is what makes the drift gate meaningful."""

    def __init__(self, indent_unit: str = "    ") -> None:
        self._lines: list[str] = []
        self._depth = 0
        self._unit = indent_unit

    def line(self, text: str = "") -> "Writer":
        self._lines.append((self._unit * self._depth + text).rstrip() if text else "")
        return self

    def lines(self, *texts: str) -> "Writer":
        for text in texts:
            self.line(text)
        return self

    def blank(self) -> "Writer":
        if self._lines and self._lines[-1] != "":
            self._lines.append("")
        return self

    def indent(self) -> "Writer":
        self._depth += 1
        return self

    def dedent(self) -> "Writer":
        self._depth = max(0, self._depth - 1)
        return self

    def block(self, header: str, open_: str = "{", close: str = "}") -> "_Block":
        return _Block(self, header, open_, close)

    def doc(self, text: str | None, prefix: str) -> "Writer":
        if not text:
            return self
        for chunk in str(text).splitlines() or [""]:
            self.line(f"{prefix} {chunk}".rstrip())
        return self

    def render(self) -> str:
        out = "\n".join(self._lines).rstrip("\n")
        return out + "\n"


class _Block:
    def __init__(self, writer: Writer, header: str, open_: str, close: str) -> None:
        self._w = writer
        self._header = header
        self._open = open_
        self._close = close

    def __enter__(self) -> Writer:
        self._w.line(f"{self._header} {self._open}".strip())
        self._w.indent()
        return self._w

    def __exit__(self, *_: object) -> None:
        self._w.dedent()
        self._w.line(self._close)


def source_label(rmap: RouteMap) -> str:
    return rmap.source.name if rmap.source else f"{rmap.service}.route-map.json"


def header_lines(rmap: RouteMap, comment: str) -> list[str]:
    out = [
        f"{comment} {BANNER.format(source=source_label(rmap))}",
        f"{comment} {PROVENANCE}",
        f"{comment}",
        f"{comment} service: {rmap.service}",
    ]
    if rmap.version:
        out.append(f"{comment} version: {rmap.version}")
    return out


def ordered_types(rmap: RouteMap) -> list[str]:
    """Type names in dependency order, so languages that care (Gleam, C-like
    headers) can declare before use. Cycles are already rejected by validation,
    so a simple post-order DFS terminates."""
    out: list[str] = []
    seen: set[str] = set()

    def deps(name: str) -> list[str]:
        defn = rmap.types.get(name)
        found: list[str] = []
        exprs: list[TypeExpr] = []
        if defn is None:
            return found
        if defn.kind == "record":
            exprs = [f.type for f in defn.fields]
        elif defn.kind == "alias":
            exprs = [defn.target]
        for expr in exprs:
            found.extend(_named_in(expr))
        return found

    def visit(name: str, stack: frozenset[str]) -> None:
        if name in seen or name in stack or name not in rmap.types:
            return
        for dep in deps(name):
            visit(dep, stack | {name})
        seen.add(name)
        out.append(name)

    for name in rmap.types:
        visit(name, frozenset())
    return out


def _named_in(expr: TypeExpr) -> list[str]:
    if isinstance(expr, Named):
        return [expr.name]
    if isinstance(expr, ListOf):
        return _named_in(expr.item)
    if isinstance(expr, MapOf):
        return _named_in(expr.value)
    if isinstance(expr, OptionOf):
        return _named_in(expr.inner)
    return []


def client_routes(rmap: RouteMap) -> list[Route]:
    """Routes worth generating a typed JSON client for.

    Server-rendered pages, redirects and static assets still belong in the map --
    the sync gate holds them to the source -- but there is no JSON call to make.
    """
    # Streaming operations are declared and validated in the map, but no
    # emitter produces a stream-returning signature yet. Emitting one as a
    # unary call would generate a client that reads the first frame and drops
    # the rest, so they are withheld until the emitters grow that shape.
    return [r for r in rmap.routes if r.client and not r.is_streaming]


def queued_routes(rmap: RouteMap) -> list[Route]:
    return [r for r in rmap.routes if r.delivery == DELIVERY_OPTO_SYNC]


def path_segments(path: str) -> list[tuple[str, bool]]:
    """Split a path template into (text, is_param) pieces, so each emitter can
    interpolate in its own syntax from one shared parse. v1 had 17 clients
    hand-writing the same path in four incompatible interpolation dialects."""
    out: list[tuple[str, bool]] = []
    buf = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == "{":
            end = path.find("}", i)
            if end == -1:
                buf += ch
                i += 1
                continue
            if buf:
                out.append((buf, False))
                buf = ""
            out.append((path[i + 1 : end], True))
            i = end + 1
            continue
        buf += ch
        i += 1
    if buf:
        out.append((buf, False))
    return out
